create or replace function lms_write_private.lock_roster_add(p_actor uuid,p_team uuid,p_candidate uuid) returns boolean
language plpgsql volatile security definer set search_path='' as $body$
begin
 if p_actor is null or p_team is null or p_candidate is null or not (exists(select 1 from public.user_roles u join public.members m on m.id=u.member_id
 where u.user_id=p_actor and m.is_active_member=true and u.role in('league_manager','commissioner')) or exists(select 1 from public.teams t join public.user_roles u on
 (u.member_id in(t.captain_member_id,t.co_captain_member_id,t.co_captain_2_member_id) and u.role='captain'
 or u.member_id=t.club_pro_member_id and u.role='club_pro')
 join public.members m on m.id=u.member_id where t.id=p_team and u.user_id=p_actor and m.is_active_member=true)) then return false; end if;
 lock table public.user_roles,public.members,public.seasons,public.leagues,public.divisions,public.locations,public.teams,public.member_season_ratings,public.team_members,lms_write_private.policy_bindings in share row exclusive mode;
 return exists(select 1 from public.teams where id=p_team) and (exists(select 1 from public.user_roles u join public.members m on m.id=u.member_id
 where u.user_id=p_actor and m.is_active_member=true and u.role in('league_manager','commissioner')) or exists(select 1 from public.teams t join public.user_roles u on
 (u.member_id in(t.captain_member_id,t.co_captain_member_id,t.co_captain_2_member_id) and u.role='captain'
 or u.member_id=t.club_pro_member_id and u.role='club_pro')
 join public.members m on m.id=u.member_id where t.id=p_team and u.user_id=p_actor and m.is_active_member=true));
end
$body$;
