 where u.user_id=p_actor and m.is_active_member=true and u.role in('league_manager','commissioner')) or exists(select 1 from public.teams t join public.user_roles u on
 (u.member_id in(t.captain_member_id,t.co_captain_member_id,t.co_captain_2_member_id) and u.role='captain'
 )
